36	/**
37	 * 真实多线程并发测试：验证 H2 行锁下不超卖、终态唯一、额度不重复释放/不变负。
38	 */
39	@SpringBootTest
40	@ActiveProfiles("test")
41	class ExposureConcurrencyTest {
42	
43	    /** 固定时钟：所有并发申请落在同一 UTC 日，预占均保持 RESERVED（不触发到期）。 */
44	    static class FixedClock extends Clock {
45	        private final Instant fixed;
46	
47	        FixedClock(Instant fixed) {
48	            this.fixed = fixed;
49	        }
50	
51	        @Override
52	        public ZoneId getZone() {
53	            return ZoneOffset.UTC;
54	        }
55	
56	        @Override
57	        public Clock withZone(ZoneId zone) {
58	            throw new UnsupportedOperationException();
59	        }
60	
61	        @Override
62	        public Instant instant() {
63	            return fixed;
64	        }
65	    }
66	
67	    static final Instant BASE = Instant.parse("2026-09-22T10:00:00Z");
68	    static final LocalDate DAY = LocalDate.of(2026, 9, 22);
69	
70	    @org.springframework.boot.test.context.TestConfiguration
71	    static class TestClockConfig {
72	        @org.springframework.context.annotation.Bean
73	        @org.springframework.context.annotation.Primary
74	        Clock fixedClock() {
75	            return new FixedClock(BASE);
76	        }
77	    }
78	
79	    @Autowired
80	    ExposureService service;
81	    @Autowired
82	    JdbcTemplate jdbc;
83	
84	    @BeforeEach
85	    void clean() {
86	        jdbc.update("DELETE FROM idempotency_record");
87	        jdbc.update("DELETE FROM exposure_reservation");
88	        jdbc.update("DELETE FROM quota_visitor_ledger");
89	        jdbc.update("DELETE FROM quota_total_ledger");
90	        jdbc.update("DELETE FROM campaign");
91	    }
