 * @param requestId 写操作全局唯一幂等键
 */
public record SuppressionReleaseRequest(
        @NotBlank @Size(max = 64) String requestId
) {
}

package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.SuppressionCancelledReservation;

import java.time.LocalDate;

/**
 * 抑制加入时被取消预占的审计明细视图。
 *
 * @param suppressionId  所属抑制周期编号
 * @param reservationId  被取消的预占单编号
 * @param campaignId     预占所属公告编号
 * @param utcDate        预占额度所属 UTC 日，格式 yyyy-MM-dd
 * @param releasedQuota  该笔释放的额度，单位次（当前恒为 1）
 * @param cancelledAtUtc 取消时刻，epoch 毫秒，UTC
 */
public record CancelledReservationView(
        String suppressionId,
        String reservationId,
        String campaignId,
        LocalDate utcDate,
        int releasedQuota,
        long cancelledAtUtc
) {
    public static CancelledReservationView from(SuppressionCancelledReservation item) {
        return new CancelledReservationView(
                item.suppressionId(),
                item.reservationId(),
                item.campaignId(),
                item.utcDate(),
                item.releasedQuota(),
                item.cancelledAtUtc());
    }
}

package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.SuppressionPeriod;

import java.util.List;

/**
 * 单个抑制周期视图：含抑制起止与该周期取消预占、额度变化明细。
 *
 * @param suppressionId        抑制周期编号
 * @param effectiveFromUtc     生效时刻，epoch 毫秒，UTC
 * @param effectiveToUtc       解除时刻；未解除为 null
 * @param cancelledCount       加入时取消的未确认预占笔数，单位笔
 * @param releasedQuota        取消预占释放的额度合计（总额度与访客额度各计该值），单位次
 * @param joinRequestId        加入名单的幂等键
 * @param releaseRequestId     解除名单的幂等键；未解除为 null
 * @param cancelledReservations 被取消预占审计明细
 */
public record SuppressionPeriodView(
        String suppressionId,
        long effectiveFromUtc,
        Long effectiveToUtc,
        int cancelledCount,
        int releasedQuota,
        String joinRequestId,
        String releaseRequestId,
        List<CancelledReservationView> cancelledReservations
) {
    public static SuppressionPeriodView from(SuppressionPeriod period,
                                             List<CancelledReservationView> cancelledReservations) {
        return new SuppressionPeriodView(
                period.suppressionId(),
                period.effectiveFromUtc(),
                period.effectiveToUtc(),
                period.cancelledCount(),
                period.releasedQuota(),
                period.joinRequestId(),
                period.releaseRequestId(),
                cancelledReservations);
    }
}

package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.Reservation;

import java.time.LocalDate;

/**
 * 访客历史已确认曝光审计视图。抑制生效后这些记录仍可审计，
 * 但不参与任何新预占发放。
 *
 * @param reservationId 预占单编号
 * @param campaignId    所属公告编号
 * @param visitorId     合成访客编号
 * @param utcDate       额度所属 UTC 日，格式 yyyy-MM-dd
 * @param createdAtUtc  创建时刻，epoch 毫秒，UTC
 * @param terminalAtUtc 确认时刻，epoch 毫秒，UTC
 */
public record ConfirmedReservationView(
        String reservationId,
        String campaignId,
        String visitorId,
        LocalDate utcDate,
        long createdAtUtc,
        long terminalAtUtc
) {
    public static ConfirmedReservationView from(Reservation reservation) {
        return new ConfirmedReservationView(
                reservation.reservationId(),
                reservation.campaignId(),
                reservation.visitorId(),
                reservation.utcDate().toLocalDate(),
                reservation.createdAtUtc(),
                reservation.terminalAtUtc() == null ? 0L : reservation.terminalAtUtc());
    }
}

